const payload = $input.first().json;
const ref = payload.pull_request?.head?.ref || 'main';
const repo = payload.repository?.full_name;

return [{
  json: {
    repo,
    branch: ref,
    commitSha: payload.pull_request?.head?.sha || payload.after,
    eventType: payload.action || 'push',
    testUrl: `https://api.example.com`
  }
}];

// 构造 k6 测试命令并执行
const testConfig = $input.first().json;

// 模拟 k6 测试结果（实际可通过 exec 节点运行 k6）
const mockResult = {
  passed: true,
  metrics: {
    http_req_duration: { 'p(95)': 210, 'p(99)': 450, avg: 85 },
    http_reqs: 1234567,
    http_req_failed: 0.00097
  },
  vus_max: 500,
  duration: '16m',
  thresholds: {
    'p(95) < 500ms': true,
    'error_rate < 1%': true
  }
};

return [{
  json: {
    ...testConfig,
    ...mockResult,
    result: mockResult.passed ? 'PASS' : 'FAIL',
    timestamp: new Date().toISOString()
  }
}];

const result = $input.first().json;
const threshold = { p95_max: 500, error_rate_max: 0.01 };

const p95Regressed = result.metrics.http_req_duration['p(95)'] > threshold.p95_max;
const errorRegressed = (result.metrics.http_req_failed / 100) > threshold.error_rate_max;

const passed = !p95Regressed && !errorRegressed;

return [{
  json: {
    ...result,
    regression_detected: !passed,
    details: {
      p95_regressed: p95Regressed,
      error_regressed: errorRegressed,
      recommendation: passed 
        ? '✅ 测试通过，可以合并 PR'
        : '⚠️ 检测到性能回归，建议修复后再合并'
    }
  }
}];

